insert into public.ce_course2_resources(id,data) values
('course2_module2_pdf','{"base64": "", "sha256": "4f676a58615653683b36cf6b15779a8a82614c1ee8a021487d2e3c547bbe1cc7", "filename": "CE_HALO_Course2_Module02_Jehovahs_Witness_Learner_FINAL.pdf", "mime_type": "application/pdf"}'::jsonb),
('course2_module2_questions','[{"module_id": "course_2_module_2", "question_id": "course_2_module_2_q01", "question_number": 1, "stem": "Which category of blood products is universally refused by Jehovah''s Witnesses regardless of source (allogeneic, directed, or predeposited autologous)? ]", "choice_a": "Whole blood, red cells, plasma, platelets, and white cells", "choice_b": "Fibrinogen concentrate and PCC", "choice_c": "Recombinant clotting factors", "choice_d": "Albumin and immunoglobulins", "correct_choice": "a", "rationale": "The primary blood components — whole blood, RBCs, plasma, platelets, and WBCs — are universally refused by JW patients regardless of source. Minor fractions and recombinant products are matters of individual conscience.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_2", "question_id": "course_2_module_2_q02", "question_number": 2, "stem": "A JW patient states she ''refuses blood.'' Which is the correct next step? ]", "choice_a": "Document the refusal in the chart and proceed with routine care", "choice_b": "Conduct a structured product-by-product review of primary components, minor fractions, autologous techniques, and hemostatic pharmacology", "choice_c": "Order predeposited autologous units to avoid transfusion", "choice_d": "Accept the statement as covering all blood-related products", "correct_choice": "b", "rationale": "A blanket ''refuses blood'' statement does not answer individual questions about minor fractions (albumin, fibrinogen concentrate, PCC, cryoprecipitate), autologous techniques (ANH, cell salvage, CPB), or nonhuman hemostatic products. Product-by-product consent is standard.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_2", "question_id": "course_2_module_2_q03", "question_number": 3, "stem": "Per the 2024 EACTS/EACTAIC PBM guideline for cardiac surgery, which two interventions are most commonly accepted by JW patients? ]", "choice_a": "Whole blood and directed donor RBCs", "choice_b": "Predeposited autologous units and platelets", "choice_c": "Coagulation factor concentrates and intraoperative cell salvage", "choice_d": "Fresh frozen plasma and cryoprecipitate", "correct_choice": "c", "rationale": "Casselman et al. (2025) state that most JW patients accept coagulation factor concentrates and intraoperative cell salvage — the two techniques central to modern bloodless cardiac surgery.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_2", "question_id": "course_2_module_2_q04", "question_number": 4, "stem": "In the Gemelli et al. (2024) meta-analysis of 780 JW and 1,182 non-JW cardiac surgery patients, what was the perioperative mortality difference? ]", "choice_a": "JW patients had significantly lower mortality (OR 0.42)", "choice_b": "Mortality was not reported", "choice_c": "JW patients had significantly higher mortality (OR 2.14)", "choice_d": "No significant difference (OR 0.91, 95% CI 0.55–1.52, p=0.72)", "correct_choice": "d", "rationale": "The 2024 meta-analysis found no significant mortality difference (OR 0.91, p=0.72), demonstrating that protocolized PBM in JW patients achieves outcomes comparable to transfusion-accepting controls.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_2", "question_id": "course_2_module_2_q05", "question_number": 5, "stem": "A JW patient with mild preoperative anemia (Hb 10.2 g/dL) is scheduled for surgery in 3 weeks. Which intervention has the highest yield for correcting anemia in this window? ]", "choice_a": "IV ferric carboxymaltose 1,000 mg, repeated at 1 week if needed", "choice_b": "Fresh frozen plasma transfusion", "choice_c": "Oral ferrous sulfate 325 mg daily", "choice_d": "Delay surgery for 12 weeks and use oral iron alone", "correct_choice": "a", "rationale": "IV iron (e.g., ferric carboxymaltose) raises Hb rapidly. In Palaia et al. (2022), JW patients receiving FCM had a mean Hb rise of 2.3 g/dL over a mean 20 days. Oral iron requires 6–8 weeks and hepcidin blockade limits daily dosing (Evans & Muñoz, 2025).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_2", "question_id": "course_2_module_2_q06", "question_number": 6, "stem": "Which oral iron regimen is preferred to maximize absorption and reduce hepcidin-mediated blockade? ]", "choice_a": "325 mg ferrous sulfate three times daily", "choice_b": "40–50 mg elemental iron daily OR 80–100 mg alternate-day", "choice_c": "Combined oral iron and vitamin B12 twice daily", "choice_d": "IV push of 500 mg elemental iron once weekly", "correct_choice": "b", "rationale": "Evans & Muñoz (2025) describe hepcidin blockade lasting 24+ hours after a high oral iron dose. Alt-day dosing (80–100 mg) or low-dose daily (40–50 mg) maximizes absorption and tolerance.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_2", "question_id": "course_2_module_2_q07", "question_number": 7, "stem": "What is the typical FDA-approved epoetin alfa regimen for preoperative optimization in an elective non-cardiac surgical patient? ]", "choice_a": "100 IU/kg IV daily for 7 days", "choice_b": "10,000 IU IV once at induction", "choice_c": "600 IU/kg SC weekly × 3 doses ending 1 day before surgery, with concurrent iron", "choice_d": "40,000 IU SC single dose intraoperatively", "correct_choice": "c", "rationale": "The FDA-approved regimen is epoetin alfa 600 IU/kg SC weekly × 3 doses ending 1 day preop, or 300 IU/kg daily × 10 days preop + 4 days postop, always with iron.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_2", "question_id": "course_2_module_2_q08", "question_number": 8, "stem": "In the ATACAS trial, high-dose tranexamic acid (100 mg/kg) compared with low-dose (50 mg/kg) in cardiac surgery produced which finding? ]", "choice_a": "No difference in transfusion or seizures", "choice_b": "Higher mortality with high-dose TXA", "choice_c": "Significantly fewer seizures with high-dose TXA", "choice_d": "Significantly reduced red-cell transfusion (21.6% vs 26.0%) with high-dose, but higher seizure rate (1.0% vs 0.4%, p=0.05)", "correct_choice": "d", "rationale": "Casselman et al. (2025) report that high-dose TXA reduced RBC transfusion but was associated with an increased seizure rate; high dose is not safer regarding seizures.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_2", "question_id": "course_2_module_2_q09", "question_number": 9, "stem": "What is the correct TXA regimen for trauma per Saxena et al. (2025) and CRASH-2? ]", "choice_a": "1 g IV within 3 hours of injury, then 1 g IV over 8 hours", "choice_b": "2 g IV bolus at hospital arrival", "choice_c": "50 mg/kg IV bolus regardless of setting", "choice_d": "10 mg/kg IV single dose regardless of time from injury", "correct_choice": "a", "rationale": "TXA 1 g IV within 3 h of injury followed by 1 g over 8 h is the standard trauma regimen. TXA administered >3 h after injury is not indicated and may be harmful.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_2", "question_id": "course_2_module_2_q10", "question_number": 10, "stem": "Per Lawal et al. (2024), what is the doctrinal requirement that most JW patients apply to acute normovolemic hemodilution? ]", "choice_a": "Blood may be stored for up to 72 hours before reinfusion", "choice_b": "The blood circuit must remain continuous with the patient''s circulation throughout collection and reinfusion", "choice_c": "ANH is universally refused", "choice_d": "Only crystalloid replacement is allowed with no blood withdrawal", "correct_choice": "b", "rationale": "Lawal et al. (2024) explicitly state that the blood circuit must remain continuous for ANH to be acceptable to many JW adherents. Their protocol maintained a slow drip (4 drops/min) during the donation phase.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_2", "question_id": "course_2_module_2_q11", "question_number": 11, "stem": "A JW patient consents to cell salvage. Which practice best preserves the continuous-circuit doctrinal requirement? ]", "choice_a": "Disconnect the reinfusion bag from IV tubing between collections", "choice_b": "Store salvaged blood in the OR refrigerator until end of case", "choice_c": "Keep the tubing from suction through wash bowl through reinfusion physically connected as one continuous circuit throughout the case", "choice_d": "Return salvaged blood only after the patient has emerged from anesthesia", "correct_choice": "c", "rationale": "A continuously connected cell-salvage circuit is the operational implementation of the JW doctrinal requirement. Disconnection or storage typically renders the salvaged blood unacceptable.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_2", "question_id": "course_2_module_2_q12", "question_number": 12, "stem": "Which product is NONHUMAN in origin and universally acceptable to JW patients per the 2025 ASH Hematology Education Program? ]", "choice_a": "Prothrombin complex concentrate", "choice_b": "Fibrinogen concentrate", "choice_c": "Cryoprecipitate", "choice_d": "Recombinant factor VIIa (NovoSeven)", "correct_choice": "d", "rationale": "Recombinant factor VIIa is a nonhuman recombinant product. Fibrinogen concentrate, PCC, and cryoprecipitate are human-plasma-derived and are matters of individual conscience.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_2", "question_id": "course_2_module_2_q13", "question_number": 13, "stem": "Which product is a HUMAN-plasma-derived fraction whose acceptability must be individually confirmed with each JW patient? ]", "choice_a": "Fibrinogen concentrate", "choice_b": "Tranexamic acid", "choice_c": "Desmopressin", "choice_d": "Recombinant factor VIII", "correct_choice": "a", "rationale": "Fibrinogen concentrate is human-plasma-derived. It is not universally accepted or refused by JW patients — it must be reviewed individually.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_2", "question_id": "course_2_module_2_q14", "question_number": 14, "stem": "In a JW patient with catastrophic hemorrhage refractory to norepinephrine and vasopressin, Saxena et al. (2025) describe which last-line rescue for refractory vasoplegia? ]", "choice_a": "Emergency transfusion of packed red blood cells", "choice_b": "Methylene blue", "choice_c": "Intravenous calcium chloride", "choice_d": "Sodium bicarbonate 8.4%", "correct_choice": "b", "rationale": "Saxena et al. (2025) describe methylene blue as a last-line rescue for refractory vasoplegia when norepinephrine and vasopressin have failed in the JW trauma patient with acute blood-loss anemia.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_2", "question_id": "course_2_module_2_q15", "question_number": 15, "stem": "A competent 45-year-old JW adult presents for elective surgery and refuses all blood products. What is the correct role of the anesthesia team? ]", "choice_a": "Proceed only after a court order overrides the refusal", "choice_b": "Administer blood if catastrophic hemorrhage develops intraoperatively", "choice_c": "Honor the documented refusal, provide all non-refused interventions, and document the plan clearly", "choice_d": "Refuse to proceed with the surgery", "correct_choice": "c", "rationale": "A competent adult has the right to refuse life-saving transfusion. The anesthesia team must honor the documented refusal even in the setting of catastrophic hemorrhage, while providing all interventions the patient has accepted.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_2", "question_id": "course_2_module_2_q16", "question_number": 16, "stem": "Which U.S. Supreme Court case established the constitutional interest in refusing unwanted medical treatment that underlies an adult''s right to refuse blood transfusion? ]", "choice_a": "Prince v. Massachusetts (1944)", "choice_b": "Roe v. Wade (1973)", "choice_c": "Griswold v. Connecticut (1965)", "choice_d": "Cruzan v. Director, Missouri Department of Health (1990)", "correct_choice": "d", "rationale": "Cruzan v. Director, Missouri Department of Health (1990) recognized a constitutional liberty interest in refusing unwanted medical treatment. Prince v. Massachusetts (1944) established that parents cannot refuse life-saving treatment for their children.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_2", "question_id": "course_2_module_2_q17", "question_number": 17, "stem": "A 4-year-old JW child requires life-saving transfusion. Parents refuse. Which principle governs? ]", "choice_a": "Parents cannot make martyrs of their children (Prince v. Massachusetts); courts routinely override refusal in the child''s best interest", "choice_b": "Only the treating physician''s judgment matters", "choice_c": "The mature-minor doctrine allows the child to consent", "choice_d": "Parental refusal is absolute for pediatric patients", "correct_choice": "a", "rationale": "Prince v. Massachusetts (1944) established that parents cannot make martyrs of their children. Courts routinely grant emergency orders authorizing transfusion in pediatric JW patients when refusal risks death or serious harm.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_2", "question_id": "course_2_module_2_q18", "question_number": 18, "stem": "According to the Wheeler & Formstone (2025) review of English pediatric judicial responses, what recommendation is made regarding clinical judgment about compulsory transfusion? ]", "choice_a": "All pediatric JW patients should be transfused without court involvement", "choice_b": "Clinical judgment should be centralized in pediatric hematology/oncology centers; clinicians should avoid seeking rolling or enduring authority", "choice_c": "Court involvement is never appropriate in pediatric JW cases", "choice_d": "Clinicians should always seek a rolling authority to compel transfusion in JW children", "correct_choice": "b", "rationale": "Wheeler & Formstone (2025) recommend centralization of clinical judgment in pediatric heme/onc centers and caution against seeking ''rolling or enduring authority'' to compel transfusion; each case should be evaluated on its own facts.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_2", "question_id": "course_2_module_2_q19", "question_number": 19, "stem": "Which of the four PBM pillars specifically addresses ''patient-centered decision-making'' in the JW context? ]", "choice_a": "Pillar 2 — minimize blood loss", "choice_b": "Pillar 1 — optimize hematopoiesis", "choice_c": "Pillar 4 — patient-centered decision-making (product-by-product consent, HLC involvement, advance directive)", "choice_d": "Pillar 3 — optimize physiologic tolerance of anemia", "correct_choice": "c", "rationale": "Pillar 4 focuses on the shared, patient-centered decisions that shape the entire PBM plan for the JW patient. All other pillars flow from what the patient has consented to.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_2", "question_id": "course_2_module_2_q20", "question_number": 20, "stem": "A pregnant JW woman refuses blood transfusion for herself. What is the U.S. legal framework? ]", "choice_a": "The state may compel transfusion to protect the fetus", "choice_b": "The husband can override her refusal", "choice_c": "The obstetrician makes the decision unilaterally", "choice_d": "A competent adult mother retains the right to refuse transfusion for herself, even if refusal may harm the fetus", "correct_choice": "d", "rationale": "Most U.S. courts have treated the pregnant JW woman as having full adult autonomy over her own body; her refusal of transfusion for herself must be honored even if it risks fetal harm.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_2", "question_id": "course_2_module_2_q21", "question_number": 21, "stem": "Which of the following ANH parameters is appropriate for a 70 kg adult JW patient with Hb 12 g/dL undergoing surgery with expected blood loss of 1 L? ]", "choice_a": "Withdraw approximately 500–1,000 mL of whole blood with isovolemic crystalloid replacement", "choice_b": "Withdraw 2,000 mL of whole blood before induction", "choice_c": "Withdraw 100 mL and discard", "choice_d": "Withdraw 1 unit and store in the OR refrigerator for 24 hours", "correct_choice": "a", "rationale": "Standard ANH withdraws approximately 10–15 mL/kg (500–1000 mL for a 70 kg adult) with continuous isovolemic crystalloid replacement. The withdrawn blood remains connected to the patient and is reinfused later in the case.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_2", "question_id": "course_2_module_2_q22", "question_number": 22, "stem": "Which is the WHO definition of severe anemia used to identify the point at which severe morbidity risk rises sharply? ]", "choice_a": "Hb <9 g/dL", "choice_b": "Hb <7 g/dL", "choice_c": "Hb <10 g/dL", "choice_d": "Hb <11 g/dL", "correct_choice": "b", "rationale": "Per WHO and Palaia et al. (2022), severe anemia is defined as Hb <7 g/dL. This is the threshold at which JW patients in the Palaia protocol also received EPO in addition to IV iron.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_2", "question_id": "course_2_module_2_q23", "question_number": 23, "stem": "Which of these is NOT an appropriate intraoperative blood-conservation strategy for a JW patient? ]", "choice_a": "Meticulous surgical hemostasis and topical hemostatics", "choice_b": "Point-of-care coagulation monitoring (TEG/ROTEM) to guide specific hemostatic use", "choice_c": "Empiric administration of fresh frozen plasma when hemoglobin drops", "choice_d": "Normothermia maintenance and avoidance of dilutional coagulopathy", "correct_choice": "c", "rationale": "Fresh frozen plasma is a primary blood component and is universally refused by JW patients. Empiric FFP is inappropriate; hemostatic therapy should be POC-guided and drawn from JW-accepted products.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_2", "question_id": "course_2_module_2_q24", "question_number": 24, "stem": "A JW patient in the ICU with severe anemia (Hb 5.4 g/dL) is hemodynamically stable. Which strategy best supports oxygen delivery? ]", "choice_a": "Administer packed red cells despite the refusal", "choice_b": "Withhold all oxygen therapy", "choice_c": "Discontinue vasopressors to reduce metabolic demand", "choice_d": "Increase FiO2 toward 1.0, optimize cardiac output, reduce oxygen consumption (sedation/paralysis), continue IV iron and EPO", "correct_choice": "d", "rationale": "Oxygen-delivery optimization for the anemic JW patient combines maximum SpO2/FiO2, cardiac-output support with volume and vasoactives, reduction of oxygen consumption (sedation, paralysis, cooling in some cases), and continued erythropoiesis-stimulating therapy.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_2", "question_id": "course_2_module_2_q25", "question_number": 25, "stem": "Which action best reflects protocolized, evidence-informed JW anesthesia practice consistent with the Gemelli et al. (2024) meta-analysis findings? ]", "choice_a": "Apply a structured multidisciplinary PBM protocol from preoperative optimization through postoperative recovery, documented and reconfirmed with the patient", "choice_b": "Skip preoperative iron optimization for time-sensitive cases", "choice_c": "Administer blood if a colleague believes it is medically necessary", "choice_d": "Cancel elective JW cases as too high-risk", "correct_choice": "a", "rationale": "The favorable outcomes in Gemelli et al. (2024) resulted from strict, protocolized, multidisciplinary PBM applied at every stage — precisely the practice standard recommended in Casselman et al. (2025).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}]'::jsonb)
on conflict(id) do update set data=excluded.data;
do $$ begin
assert (select encode(sha256(decode(data->>'base64','base64')),'hex')=data->>'sha256' from public.ce_course2_resources where id='course2_module2_pdf'),'PDF hash mismatch';
assert (select released=false from public.ce_course2_catalog where id='1047241'),'Course must remain staged';
end $$;
commit;